describe('Colour Contrast WCAG 2.1 AA Compliance', () => {
  beforeEach(() => {
    cy.visit('/contrast-checker');
  });

  it('should display high contrast colours meeting WCAG AA standards', () => {
    // Verify the contrast checker is visible
    cy.get('[data-testid="contrast-checker"]').should('be.visible');

    // Verify the default text and background have sufficient contrast
    cy.get('[data-testid="text-input"]').should('have.attr', 'style', 'color: #000000;');
    cy.get('[data-testid="background-panel"]').should('have.attr', 'style', 'background-color: #ffffff;');

    // Verify the contrast ratio is displayed and meets AA standard (4.1:1 for normal text)
    cy.get('[data-testid="contrast-ratio"]').should('contain', '4.1:1');
    cy.get('[data-testid="contrast-status"]').should('contain', 'Meets WCAG AA');

    // Verify the contrast status indicator is green
    cy.get('[data-testid="contrast-status-indicator"]').should('have.class', 'status-success');

    // Verify the contrast ratio is displayed in the correct format
    cy.get('[data-testid="contrast-ratio"]').should('match', /^\d+\.\d+\/\d+\.\d+$/);
  });

  it('should flag low contrast colours and provide remediation suggestions', () => {
    // Intercept the API call to simulate a low contrast scenario
    cy.intercept('GET', '/api/contrast-check').as('lowContrastCheck');

    // Click the button to check contrast with low contrast colours
    cy.get('[data-testid="check-contrast-button"]').click();

    // Verify the API call was made
    cy.wait('@lowContrastCheck');

    // Verify the contrast ratio is displayed and fails AA standard
    cy.get('[data-testid="contrast-ratio"]').should('contain', '2.1:1');
    cy.get('[data-testid="contrast-status"]').should('contain', 'Fails WCAG AA');

    // Verify the contrast status indicator is red
    cy.get('[data-testid="contrast-status-indicator"]').should('have.class', 'status-error');

    // Verify remediation suggestions are displayed
    cy.get('[data-testid="remediation-suggestions"]').should('be.visible');
    cy.get('[data-testid="remediation-suggestions"]').should('contain', 'Increase text contrast');
    cy.get('[data-testid="remediation-suggestions"]').should('contain', 'Use darker background');

    // Verify the user can click on a suggestion to apply it
    cy.get('[data-testid="suggest-darker-background"]').click();
    cy.get('[data-testid="contrast-ratio"]').should('contain', '4.1:1');
    cy.get('[data-testid="contrast-status"]').should('contain', 'Meets WCAG AA');
  });
});
